import sqlite3

#main has been chanegd to main from app
main = Flask(__name__)

# Used by Flask to protect session data.
# Fine for local development, but use an environment variable
# with a random secret in production.
main.secret_key = "development-secret-key"

DATABASE = "database.db"


# ============================================================
# DATABASE
# ============================================================

def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row

    # Enable SQLite foreign keys for this connection
    conn.execute("PRAGMA foreign_keys = ON")

    return conn


# ============================================================
# HOME PAGE
# ============================================================

@main.route("/")
def index():
    conn = get_db()
    restaurants = conn.execute("SELECT * FROM restaurants").fetchall()
    conn.close()
    return render_template("index.html",restaurants=restaurants)


