# ============================================================
# add to cart
# ============================================================

@main.route("/cart/add/<int:item_id>", methods=["POST"])
def add_to_cart(item_id):

    # User must be logged in
    if "user_id" not in session:
        return redirect(url_for("login"))

    conn = get_db()
    item = conn.execute("""SELECT * FROM menu_items WHERE id = ?""",(item_id,)).fetchone()

    conn.close()

    if item is None:
        abort(404)

    # Create a cart if one does not exist
    cart = session.get("cart", {})
    item_key = str(item_id)

    # Increase quantity if already in cart
    if item_key in cart:
        cart[item_key] += 1
    else:
        cart[item_key] = 1

    session["cart"] = cart

    return redirect(url_for("restaurant",restaurant_id=item["restaurant_id"]))


# ============================================================
# cart page
# ============================================================

@main.route("/cart")
def cart():
    if "user_id" not in session:
        return redirect(url_for("login"))

    cart_data = session.get("cart", {})
    items = []
    total = 0
    conn = get_db()

    for item_id, quantity in cart_data.items():
        item = conn.execute("""SELECT * FROM menu_items WHERE id = ?""",(item_id,)).fetchone()
        if item is not None:
            subtotal = item["price"] * quantity
            total += subtotal
            items.append({
                "id": item["id"],
                "name": item["name"],
                "price": item["price"],
                "quantity": quantity,
                "subtotal": subtotal
            })
    conn.close()
    return render_template("cart.html",items=items,total=total)

