# increase and decrease cart
# ============================================================

@main.route("/cart/increase/<int:item_id>", methods=["POST"])
def increase_cart_item(item_id):

    if "user_id" not in session:
        return redirect(url_for("login"))

    cart = session.get("cart", {})

    item_key = str(item_id)

    if item_key in cart:
        cart[item_key] += 1

    session["cart"] = cart

    return redirect(url_for("cart"))

@main.route("/cart/decrease/<int:item_id>", methods=["POST"])
def decrease_cart_item(item_id):

    if "user_id" not in session:
        return redirect(url_for("login"))

    cart = session.get("cart", {})

    item_key = str(item_id)

    if item_key in cart:

        cart[item_key] -= 1

        if cart[item_key] <= 0:
            del cart[item_key]

    session["cart"] = cart

    return redirect(url_for("cart"))

@main.route("/cart/remove/<int:item_id>", methods=["POST"])
def remove_cart_item(item_id):

    if "user_id" not in session:
        return redirect(url_for("login"))

    cart = session.get("cart", {})

    item_key = str(item_id)

    if item_key in cart:
        del cart[item_key]

    session["cart"] = cart

    return redirect(url_for("cart"))

# ============================================================
# checkout
# ============================================================

@main.route("/checkout", methods=["POST"])
def checkout():

    if "user_id" not in session:
        return redirect(url_for("login"))

    cart = session.get("cart", {})
    if not cart:
        return redirect(url_for("cart"))

    address = request.form["address"].strip()
    if not address:
        return redirect(url_for("cart"))

    conn = get_db()
    try:
        cursor = conn.execute(
            """
            INSERT INTO orders
                (user_id, address, status)
            VALUES
                (?, ?, ?)
            """,
            (
                session["user_id"],
                address,
                "pending"
            )
        )

        order_id = cursor.lastrowid
        for item_id, quantity in cart.items():

            # Verify that the menu item actually exists
            item = conn.execute(
                """
                SELECT id
                FROM menu_items
                WHERE id = ?
                """,
                (item_id,)
            ).fetchone()

            if item is None:
                continue

            conn.execute(
                """
                INSERT INTO order_items
                    (order_id, menu_item_id, quantity)
                VALUES
                    (?, ?, ?)
                """,
                (
                    order_id,
                    item_id,
                    quantity
                )
            )

        conn.commit()

    except Exception:
        conn.rollback()
        conn.close()
        raise

    conn.close()

    # Empty the cart after successful checkout
    session["cart"] = {}

    return redirect(
        url_for(
            "order_confirmation",
            order_id=order_id
        )
    )

# ============================================================
# confirmation
# ============================================================
@main.route("/order/<int:order_id>")
def order_confirmation(order_id):

    if "user_id" not in session:
        return redirect(url_for("login"))

    conn = get_db()

    order = conn.execute(
        """
        SELECT *
        FROM orders
        WHERE id = ?
        AND user_id = ?
        """,
        (
            order_id,
            session["user_id"]
        )
    ).fetchone()

    if order is None:
        conn.close()
        abort(404)

    items = conn.execute(
        """
        SELECT
            menu_items.name,
            menu_items.price,
            order_items.quantity

        FROM order_items

        JOIN menu_items
        ON menu_items.id = order_items.menu_item_id

        WHERE order_items.order_id = ?
        """,
        (order_id,)
    ).fetchall()

    conn.close()

    total = sum(
        item["price"] * item["quantity"]
        for item in items
    )

    return render_template(
        "order.html",
        order=order,
        items=items,
        total=total
    )
